const indent = 2;
export class ExportJSONPluginInstance {
    #container;
    constructor(container) {
        this.#container = container;
    }
    async export(type) {
        const res = {
            supported: false,
        };
        switch (type) {
            case "json":
                res.supported = true;
                res.blob = await this.#exportJSON();
                break;
        }
        return res;
    }
    #exportJSON = async () => {
        const json = JSON.stringify(this.#container.actualOptions, (key, value) => {
            if (key.startsWith("_")) {
                return;
            }
            return value;
        }, indent);
        return Promise.resolve(new Blob([json], { type: "application/json" }));
    };
}
